namespace HakutaiKagami.Core.Contracts;
public sealed record CustodyReturnPlan(EntityId Destination,EntityId RecipientHouse,EntityId AgreedRecipient,Intent Travel);
public static partial class HostageCustody
{
    static CustodyEntry? LatestReturn(CustodyEntry[] rows,EntityId root)=>Case(rows,root).LastOrDefault(e=>e.Return!=null);
    static CustodyEntry? ReturnFor(ContractWorld w,EntityId person,long at,long rev){var rows=Before(w,at,rev);var roots=rows.Where(e=>e.Terms?.Person==person).Select(e=>e.Input.Id).ToArray();return rows.LastOrDefault(e=>e.Return!=null&&e.Input.Original is {} root&&roots.Contains(root));}
    internal static BranchJourney? ReturnJourney(ContractWorld w,EntityId person,long at,long rev){var e=ReturnFor(w,person,at,rev);if(e==null)return null;var task=w.Tasks.SingleOrDefault(t=>t.RequestId==e.Return!.Travel.RequestId);if(task==null)return null;var j=w.Branches!.Journeys.SingleOrDefault(j=>j.Task==task.Id&&j.Legs[0].StartAt<=at);if(j==null)return null;if(w.Branches.Journeys.Any(x=>x.Actor==person&&x.Legs[0].StartAt<=at&&x.Legs[0].StartAt>=j.Legs[0].StartAt))return null;return j;}
    internal static bool HasReturnHistory(ContractWorld w,EntityId person)=>Entries(w).Any(e=>e.Terms?.Person==person&&LatestReturn(Entries(w),e.Input.Id)!=null);
    internal static RoutePoint? ReturnPoint(ContractWorld w,EntityId person,long at,long rev)=>ReturnJourney(w,person,at,rev) is {} j?RegionalCampaign.JourneyPointAt(w,j,at):null;
    internal static EntityId? ReturnSite(ContractWorld w,EntityId person,long at,long rev){var point=ReturnPoint(w,person,at,rev);if(point==null)return null;var node=BranchRoutes.GraphNodes(w).SingleOrDefault(n=>n.Position==point);return node==null?null:RegionalCampaign.Site(node.Id);}
    internal static bool ActiveReturn(ContractWorld w)=>Entries(w).Any(e=>e.Terms!=null&&Held(Entries(w),e.Input.Id)&&LatestReturn(Entries(w),e.Input.Id)!=null);
    internal static bool IsReturnTask(ContractWorld w,Intent i)=>Entries(w).Any(e=>e.Return?.Travel==i);
    static Intent MakeReturnTask(ContractWorld w,CustodyEntry e,EntityId site){var before=PersonalCompanions.BeforeTask(w,new CompanionOrder(new(e.Input.Id,w.PlayerControl,CompanionAction.TravelTogether,Destination:NewGameWorld.Node(site.Value)),e.At,e.Revision,PersonalCompanions.PhysicalSiteAt(w,w.PlayerControl,e.At,e.Revision)??throw new InvalidDataException("護送者の所在がありません"),null,null));return TravelWorld.ActorMove(before,"request:custody-return-task/"+ContractJson.CanonicalHash(e.Input.Id),w.PlayerControl,NewGameWorld.Node(site.Value),true,PersonalCompanions.LandRoute);}
    static CustodyReturnPlan PrepareReturn(ContractWorld w,CustodyEntry e,CustodyTerms t,CustodyEntry[] prior){
        Need(e.Actor==t.Guardian&&Held(prior,t.Id),"同じ本人の返還保証が必要です");var old=LatestReturn(prior,t.Id);EntityId destination;EntityId recipient;
        if(e.Input.Action==CustodyAction.StartReturn){Need(old==null&&LocalOriginal(w,t,e.At,e.Revision)&&LocalAuthorities(w,Effective(t,prior),e.At,e.Revision),"現地の本人と確認済みの両家で護送を承諾してください");Need(!NewGameMilitary.LedgerStates(w).Any(s=>{var c=w.ForkMilitaryObservation();c.NewMilitary=s;return NewGameMilitary.CustodyAt(c,e.At,e.Revision);}),"預かった軍の役目を先に返してください");destination=new(w.NewGame!.Start.Factions.Single(f=>f.Id==t.GuardianHouse.Value).Home);recipient=Effective(t,prior).Guardian;Need(destination!=t.Site,"同じ場所への護送ではありません");}
        else{Need(old!=null&&w.Tasks.Any(task=>task.RequestId==old.Return!.Travel.RequestId&&task.Execution is ExecutionPhase.Stopped or ExecutionPhase.Failed&&task.FinishedAt<=e.At),"停止した同じ護送だけを再開できます");destination=old.Return!.Destination;recipient=old.Return.AgreedRecipient;Need(PersonalCompanions.PhysicalSiteAt(w,t.Guardian,e.At,e.Revision) is {} site&&ReturnSite(w,t.Person,e.At,e.Revision)==site,"護送者と本人が同じ停止地点にいる必要があります");}
        return new(destination,t.GuardianHouse,recipient,MakeReturnTask(w,e,destination));
    }
    static EntityId PrepareReceipt(ContractWorld w,CustodyEntry e,CustodyTerms t,CustodyEntry[] prior){var trip=LatestReturn(prior,t.Id);Need(e.Actor==t.Guardian&&Held(prior,t.Id)&&trip!=null,"同じ本人の護送原本が必要です");Need(w.Tasks.Any(task=>task.RequestId==trip.Return!.Travel.RequestId&&task.Execution==ExecutionPhase.Completed&&task.FinishedAt<=e.At),"返還先への到着を待ってください");var p=trip.Return!;var recipient=HouseSuccession.Head(w,p.RecipientHouse,e.At,e.Revision-1);Need(PersonalCompanions.PhysicalSiteAt(w,t.Guardian,e.At,e.Revision)==p.Destination&&ReturnSite(w,t.Person,e.At,e.Revision)==p.Destination&&PersonalCompanions.PhysicalSiteAt(w,recipient,e.At,e.Revision)==p.Destination&&FactionStances.ResolveAuthority(w,recipient,p.RecipientHouse,e.At,e.Revision-1)!=null&&(recipient==w.PlayerControl||w.Characters.Single(c=>c.Id==recipient).WillObey),"到着先で現在の受領権者と本人を確認してください");return recipient;}
    internal static void SyncReturn(ContractWorld w){foreach(var p in Entries(w).Where(e=>e.Terms!=null)){var t=p.Terms!;if(!Held(Entries(w),t.Id)||LatestReturn(Entries(w),t.Id)==null||ReturnJourney(w,t.Person,w.ElapsedSeconds,w.CommitSequence+1)==null)continue;var leader=w.Locations.Single(l=>l.Actor==t.Guardian);w.Locations=w.Locations.Select(l=>l.Actor==t.Person?leader with{Actor=t.Person}:l).ToArray();}}
    static void ValidateReturn(ContractWorld w,ContractWorld? prior){foreach(var e in Entries(w).Where(e=>e.Return!=null)){var request=w.Requests.SingleOrDefault(r=>r.Id==e.Return!.Travel.RequestId);Need(request!=null?request.Intent==e.Return!.Travel&&request.CommitSequence>e.Revision:prior!=null,"護送原本と共通移動が一致しません");}foreach(var p in Entries(w).Where(e=>e.Terms!=null)){var t=p.Terms!;var j=ReturnJourney(w,t.Person,w.ElapsedSeconds,w.CommitSequence+1);if(j==null)continue;var location=w.Locations.Single(l=>l.Actor==t.Person);var point=RegionalCampaign.JourneyPointAt(w,j,w.ElapsedSeconds);if(Held(Entries(w),t.Id)){Need(RegionalCampaign.RoadActorPointAt(w,t.Guardian,w.ElapsedSeconds)==point,"本人を残して護送者だけ移動できません");Need(location==(w.Locations.Single(l=>l.Actor==t.Guardian) with{Actor=t.Person}),"護送者と本人の所在が分離しています");}else Need(location.Kind==LocationKind.AtSite&&location.Site==LatestReturn(Entries(w),t.Id)!.Return!.Destination,"返還後の本人の所在が違います");}}
    public static bool CanStartReturn(ContractWorld w,EntityId root){var p=Entries(w).SingleOrDefault(e=>e.Input.Id==root);return p?.Terms is {} t&&Held(Entries(w),root)&&LatestReturn(Entries(w),root)==null&&LocalOriginal(w,t,w.ElapsedSeconds,w.CommitSequence+1)&&LocalAuthorities(w,Effective(t,Entries(w)),w.ElapsedSeconds,w.CommitSequence+1);}
    public static bool CanResumeReturn(ContractWorld w,EntityId root){var r=LatestReturn(Entries(w),root);return Held(Entries(w),root)&&r!=null&&w.Tasks.Any(t=>t.RequestId==r.Return!.Travel.RequestId&&t.Execution is ExecutionPhase.Stopped or ExecutionPhase.Failed);}
    public static bool CanReceiveReturn(ContractWorld w,EntityId root){var r=LatestReturn(Entries(w),root);return Held(Entries(w),root)&&r!=null&&w.Tasks.Any(t=>t.RequestId==r.Return!.Travel.RequestId&&t.Execution==ExecutionPhase.Completed);}
}
